using Lastlight.Core;
public static class RegionEdges
{
 public static void Run(Definitions d,string output)
 {
  Directory.CreateDirectory(output);void Require(bool v,string m){if(!v)throw new Exception(m);}void Steps(World w,int n){for(int i=0;i<n;i++)w.Step(d);}void Command(World w,WorldCommand c){var r=w.Apply(c,d);Require(r.Accepted,r.Message);}World Camp(){var w=LivingWorldGenerator.Create(d,74219);var r=w.Apply(new(CommandKind.Spawn,DefinitionId:"meal",X:62,Y:67,Quantity:8),d);Require(r.Accepted,r.Message);return w;}
  var packing=Camp();long leader=packing.Colony.People.Keys.First();var site=packing.Region.Sites.First(s=>s.Kind=="University");int meals=packing.Resources("meal").Total,brass=packing.Resources("brass").Total;Command(packing,new(CommandKind.RegionAction,leader,leader.ToString(),TargetId:site.Id,Quantity:2,Text:"depart"));
  for(int i=0;i<5000&&!packing.Autonomy.Jobs.Any(j=>j.Kind=="Provision"&&j.Cargo.Count>0);i++)packing.Step(d);Require(packing.Autonomy.Jobs.Any(j=>j.Kind=="Provision"&&j.Cargo.Count>0),"No packing cargo checkpoint.");Command(packing,new(CommandKind.Draft,leader,Quantity:1));Steps(packing,30);Require(packing.Region.Parties.Last().State=="Cancelled"&&packing.Region.Absent.Count==0&&packing.Resources("meal").Total>=meals&&packing.Resources("brass").Total==brass,"Cancelled packing lost real supplies or stranded members.");packing.Validate(d);Console.WriteLine("PASS G03 edge: interruption refunds carried provisions and cancels the party without absent actors");
  var away=Camp();leader=away.Colony.People.Keys.First();Command(away,new(CommandKind.RegionAction,leader,leader.ToString(),TargetId:away.Region.Sites.First(s=>s.Kind=="University").Id,Text:"depart",Quantity:2));for(int i=0;i<5000&&away.Region.Parties.Last().State!="Outbound";i++)away.Step(d);Require(away.IsAway(leader),"Traveler did not leave home.");int home=away.Region.Parties.Last().HomeCells[leader];var p=away.Find(leader)!;var wood=away.Apply(new(CommandKind.Spawn,DefinitionId:"wood",X:p.X,Y:p.Y,Z:p.Z,Quantity:10),d);Require(wood.Accepted,wood.Message);away.Physical.Fires[home]=new(){Intensity=3};int health=p.Health;Steps(away,300);Require(p.Health==health,"Off-map traveler injured by a home fire.");away.Validate(d);Console.WriteLine("PASS G03 edge: traveling residents cannot work, fight or receive home environmental exposure");
  var permissions=Camp();leader=permissions.Colony.People.Keys.First();var town=permissions.Region.Sites.First(s=>s.Kind=="Town");var faction=permissions.Region.Factions.First(f=>f.Id==town.FactionId);faction.Goodwill=-50;Require(!permissions.Apply(new(CommandKind.RegionAction,leader,leader.ToString(),TargetId:town.Id,Text:"depart",Quantity:2),d).Accepted,"Blocked faction accepted an expedition.");permissions.Region.Treaties.Add(new(){Id=permissions.Region.NextId++,FactionId=faction.Id,Kind="Safe passage",SignedAt=permissions.Tick});Command(permissions,new(CommandKind.RegionAction,leader,leader.ToString(),TargetId:town.Id,Text:"depart",Quantity:2));permissions.Validate(d);Console.WriteLine("PASS G04 edge: route/entry permission changes with a signed safe-passage treaty");
  var tribute=Camp();var payer=tribute.Region.Factions[1];var treaty=new RegionTreaty{Id=tribute.Region.NextId++,FactionId=payer.Id,Kind="Tribute",Payment=3,SignedAt=0,DueAt=1};tribute.Region.Treaties.Add(treaty);Steps(tribute,World.TicksPerDay);Require(!treaty.Active&&payer.Grievance>=10,"Missed tribute lacked a persistent consequence.");tribute.Validate(d);Console.WriteLine("PASS G04 edge: concrete tribute obligation expires, ends access terms and creates a grievance");
  var traderWorld=Camp();var exporting=traderWorld.Region.Factions[0];int medicine=exporting.Reserves["medicine"];Steps(traderWorld,World.TicksPerDay*3+World.TicksPerHour*2+30);var trader=traderWorld.Region.Traders.First(t=>t.State=="Visiting");Require(exporting.Reserves["medicine"]==medicine-3&&trader.Cargo["medicine"]==3,"Trader exports were fabricated.");leader=traderWorld.Colony.People.Keys.First();int localMedicine=traderWorld.Resources("medicine").Total;Command(traderWorld,new(CommandKind.RegionAction,leader,"medicine",TargetId:trader.Id,Quantity:1,Text:"visitor-buy"));for(int i=0;i<6000&&trader.Cargo["medicine"]==3;i++)traderWorld.Step(d);Require(trader.Cargo["medicine"]==2&&traderWorld.Resources("medicine").Total==localMedicine+1&&trader.Cargo["brass"]==2,"Physical visiting trade failed conservation.");Steps(traderWorld,World.TicksPerDay);Require(trader.State=="Returned"&&trader.Cargo.Count==0&&exporting.Reserves["medicine"]==medicine-1,"Returning trader duplicated or lost unsold exports.");traderWorld.Validate(d);SaveStore.Write(Path.Combine(output,"visiting-trader-completed.lastlight"),traderWorld,new ViewState{CameraX=64,CameraY=64,OpenTab="Factions"},d);Console.WriteLine("PASS G04 edge: reserve-funded visiting caravan, physical payment job and single return of receipts/unsold stock");
  var relief=Camp();var ally=relief.Region.Factions[1];int stock=ally.Reserves["medicine"];relief.Region.Treaties.Add(new(){Id=relief.Region.NextId++,FactionId=ally.Id,Kind="Mutual defense",SignedAt=0});relief.Danger.Raid.Phase="Warning";relief.Danger.Raid.WarningUntil=relief.Tick+World.TicksPerDay;Steps(relief,30);Require(relief.Region.Traders.Any(t=>t.Relief)&&ally.Reserves["medicine"]==stock-2,"Mutual defense did not dispatch real relief.");relief.Danger.Raid.Phase="Idle";Steps(relief,World.TicksPerHour*2+30);Require(relief.Region.Traders.All(t=>t.State=="Returned")&&relief.Region.History.Any(h=>h.Kind=="Diplomacy"&&h.Text.Contains("arrived")),"Treaty relief did not arrive exactly once.");relief.Validate(d);Console.WriteLine("PASS G04 edge: mutual-defense response consumes ally reserves and delivers real relief");
 }
}
